// C++17
#include <iostream>
#include <type_traits>

static_assert(std::is_integral_v<int>);   // compile-time fact

template<typename T>
int kind(T) {
    return std::is_integral_v<T> ? 1 : 0; // queried per instantiation
}

int main() {
    std::cout << kind(7) << kind(7.0) << kind('a');   // 101
}

// C++17 (enable_if_t is C++14)
#include <iostream>
#include <type_traits>

template<typename T, std::enable_if_t<std::is_integral_v<T>, int> = 0>
const char* pick(T) { return "integral"; }

template<typename T, std::enable_if_t<std::is_floating_point_v<T>, int> = 0>
const char* pick(T) { return "floating"; }

int main() { std::cout << pick(3) << " " << pick(3.5) << "\n"; }   // integral floating

// C++17
#include <iostream>
#include <type_traits>

template<typename T>
T half(T x) {
    if constexpr (std::is_integral_v<T>)
        return x / 2;          // integer division
    else
        return x / T(2);       // true division
}

int main() {
    std::cout << half(7) << " " << half(7.0) << "\n";   // 3 3.5
}

// C++20 - concepts
#include <concepts>
#include <iostream>

template<std::integral T>
T half(T x) { return x / 2; }          // integer division

template<std::floating_point T>
T half(T x) { return x / 2; }          // true division

int main() {
    std::cout << half(7) << " " << half(7.0) << "\n";   // 3 3.5
}

